<?php
namespace Tests\Feature;
use Tests\TestCase;use Tests\CreatesLedgerCompany;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Services\{SalesService,PaymentService,FxRevaluationService,DocumentBalanceService};use App\Models\ExchangeRate;use Illuminate\Support\Facades\DB;
class FxAccountingTest extends TestCase {use RefreshDatabase,CreatesLedgerCompany;
 public function test_period_end_revaluation_is_incremental_and_realized_fx_uses_revalued_carrying_amount():void{[$c,$u,$a]=$this->company();$this->actingAs($u);$usd=$this->usd();$customer=$this->customer($c);$i=app(SalesService::class)->createDraft($c->id,$u->id,['contact_id'=>$customer->id,'invoice_date'=>'2026-01-10','currency_id'=>$usd->id,'exchange_rate'=>'0.700'],[['description'=>'USD service','quantity'=>'1','unit_price'=>'100','revenue_account_id'=>$a['4100']->id]]);$i=app(SalesService::class)->post($i,$u->id);$this->assertSame('70.000',$i->base_total);ExchangeRate::create(['company_id'=>$c->id,'currency_id'=>$usd->id,'rate_date'=>'2026-01-31','rate'=>'0.710','created_by'=>$u->id]);$j1=app(FxRevaluationService::class)->run($c->id,$u->id,'2026-01-31');$this->assertNotNull($j1);$this->assertSame('71.000',app(DocumentBalanceService::class)->sales($i,'2026-01-31')['base']);ExchangeRate::create(['company_id'=>$c->id,'currency_id'=>$usd->id,'rate_date'=>'2026-02-28','rate'=>'0.715','created_by'=>$u->id]);$j2=app(FxRevaluationService::class)->run($c->id,$u->id,'2026-02-28');$this->assertNotNull($j2);$adj=\App\Models\FxRevaluationItem::where('journal_id',$j2->id)->value('carrying_adjustment');$this->assertSame('0.500',(string)$adj);$p=app(PaymentService::class)->receive($c->id,$u->id,['contact_id'=>$customer->id,'payment_date'=>'2026-03-01','currency_id'=>$usd->id,'amount'=>'100','exchange_rate'=>'0.720','cash_account_id'=>$a['1110']->id],[['document_id'=>$i->id,'amount'=>'100']]);$alloc=$p->allocations()->first();$this->assertSame('71.500',(string)$alloc->base_amount);$this->assertSame('0.500',(string)$alloc->realized_fx);}
 public function test_no_adjustment_revaluation_returns_null():void{[$c,$u,$a]=$this->company();$this->actingAs($u);$usd=$this->usd();$customer=$this->customer($c);$i=app(SalesService::class)->createDraft($c->id,$u->id,['contact_id'=>$customer->id,'invoice_date'=>'2026-01-10','currency_id'=>$usd->id,'exchange_rate'=>'0.700'],[['description'=>'USD service','quantity'=>'1','unit_price'=>'100','revenue_account_id'=>$a['4100']->id]]);app(SalesService::class)->post($i,$u->id);ExchangeRate::create(['company_id'=>$c->id,'currency_id'=>$usd->id,'rate_date'=>'2026-01-31','rate'=>'0.700','created_by'=>$u->id]);$this->assertNull(app(FxRevaluationService::class)->run($c->id,$u->id,'2026-01-31'));}
}
